use component::{Component, Wrapper};
use core::cell::OnceCell;

// --- These are for test purpose

// This struct should be autogenerated.
struct UserContext {
    username: &'static str,
    age: u32,
}

struct User {
    context: UserContext,
    // Internal variables
    nb_time_printed: u32,
}

impl User {
    fn new(context: UserContext) -> Self {
        Self {
            context,
            nb_time_printed: 1,
        }
    }

    fn print_info(&mut self) {
        println!(
            "User: {}, Age: {}, printed: {} time(s)",
            self.context.username, self.context.age, self.nb_time_printed
        );
        self.nb_time_printed += 1;
    }
}

