fn main() {
    let user_context = UserContext {
        age: 28,
        username: "Alex",
    };
    let mut user = Wrapper::new(Component {
        instance: User::new(user_context),
        on_init: || async { Ok::<(), bzd::base::error::Error>(()) },
        on_shutdown: || async { Ok::<(), bzd::base::error::Error>(()) },
    });

    user.instance.print_info();
    user.instance.print_info();

    println!("hello");
}
